import {npxDrape,npxSpecimen} from './npx-art.js';
export const ORAL_POINTS=[{x:35,y:45,label:'左側'},{x:66,y:48,label:'右側'},{x:51,y:68,label:'下方'}];
export const EAR_POINTS=[{id:'anterior-superior',x:38,y:35,label:'前上方'},{id:'posterior-superior',x:62,y:35,label:'後上方'},{id:'anterior-inferior',x:38,y:65,label:'前下方'},{id:'posterior-inferior',x:62,y:65,label:'後下方'}];
const svg=(content,label,viewBox='0 0 480 320')=>`<svg viewBox="${viewBox}" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg">${content}</svg>`;
export function localTool(id){
  const drawing={spray:'<rect x="60" y="39" width="42" height="45" rx="7" fill="#e7e8d8" stroke="#819b92"/><path d="M72 39V25h25l15 7" fill="none" stroke="#54776f" stroke-width="8"/><path d="M117 28l25-9m-23 17h29m-29 7l23 9" stroke="#a5c5b6" stroke-width="3"/>',syringe:'<g transform="rotate(-25 85 48)"><path d="M28 48h27m60 0h33" stroke="#a1b7b7" stroke-width="3"/><rect x="55" y="35" width="61" height="26" rx="3" fill="#e7eee4" stroke="#8da9a0"/><path d="M53 28v40m-25-30v20m42-22v13m13-13v13m13-13v13" stroke="#719489" stroke-width="3"/></g>',injection:'<g transform="rotate(-25 85 48)"><path d="M28 48h27m60 0h30" stroke="#acc3bd" stroke-width="3"/><rect x="55" y="35" width="61" height="26" rx="3" fill="#d4e6da" stroke="#6d9d90"/><path d="M56 36h32v24H56" fill="#8cb8a8"/><path d="M53 28v40m-25-30v20" stroke="#719489" stroke-width="4"/></g>',biopsy:'<g stroke="#9ab3b2" stroke-width="5" fill="none"><path d="M42 71l87-43m-87 34l87-28"/><ellipse cx="33" cy="75" rx="12" ry="8"/><ellipse cx="33" cy="55" rx="12" ry="8"/><path d="M130 28l13-7m-13 13l13-1"/></g>',cautery:'<path d="M31 76q-20 12-14 18" stroke="#5e7c77" stroke-width="4" fill="none"/><path d="M36 72l61-35" stroke="#78a5a1" stroke-width="15" stroke-linecap="round"/><path d="M98 37l31-17" stroke="#b7c9bf" stroke-width="4"/><circle cx="70" cy="52" r="5" fill="#d7c780"/>',headlamp:'<path d="M41 63q-2-49 46-45 40 4 39 46" fill="none" stroke="#526c73" stroke-width="10"/><rect x="66" y="36" width="42" height="31" rx="8" fill="#6f9992"/><circle cx="88" cy="51" r="11" fill="#e8dcb7" stroke="#c4cdb8" stroke-width="4"/>',swab:'<path d="M40 76l90-49" stroke="#ad9b79" stroke-width="5"/><path d="M125 30l15-8" stroke="#f5f0df" stroke-width="14" stroke-linecap="round"/>'}[id]||'';
  return svg(`<rect width="170" height="100" rx="8" fill="#d7e2d5"/>${drawing}`,id==='headlamp'?'頭燈':'本台使用物品','0 0 170 100');
}
export function earView(t){return svg(`<defs><radialGradient id="ear-skin"><stop stop-color="#d2b99f"/><stop offset=".72" stop-color="#9d8274"/><stop offset="1" stop-color="#394349"/></radialGradient></defs><rect width="480" height="320" rx="12" fill="#1d3d43"/><circle cx="240" cy="160" r="137" fill="url(#ear-skin)"/><circle cx="240" cy="160" r="109" fill="#bdb8a3" stroke="#dfcbb1" stroke-width="6"/><path d="M234 66l15 81-15 29" fill="none" stroke="#e3d7bc" stroke-width="8"/><path d="M229 161q-33 23-37 67" stroke="#eee2c4" stroke-width="4" fill="none" opacity=".7"/><path d="M131 160h218m-109-109v218" stroke="#d8cbb3" stroke-width="1" stroke-dasharray="4 5" opacity=".8"/>${t.found?'<circle cx="182" cy="208" r="23" fill="none" stroke="#d7d8a6" stroke-width="3"/>':''}${t.stage==='inject'?'<path d="M360 293l-155-74" stroke="#b5c8c0" stroke-width="5"/><path d="M345 283l-47-22" stroke="#7ca99a" stroke-width="16"/>':''}${t.injected?'<circle cx="182" cy="208" r="4" fill="#a57e6c"/>':''}<g fill="#d7e3d4" font-size="12"><text x="240" y="24" text-anchor="middle">上</text><text x="240" y="309" text-anchor="middle">下</text><text x="61" y="164">前</text><text x="407" y="164">後</text></g><text x="20" y="27" font-size="10" letter-spacing="1" fill="#bed1c3">EAR / SIMPLIFIED VIEW</text>`,'耳內視鏡簡化示意：上、下、前、後方向已標示');}
export function oralView(t){const p=ORAL_POINTS[t.lesion],x=p.x*4.8,y=p.y*3.2;return svg(`<defs><radialGradient id="oral-tissue"><stop stop-color="#c79888"/><stop offset="1" stop-color="#755757"/></radialGradient></defs><rect width="480" height="320" rx="12" fill="#234047"/><path d="M74 137q27-89 166-89 144 0 166 89-15 130-166 139-149-9-166-139" fill="#b8867b"/><ellipse cx="240" cy="163" rx="148" ry="103" fill="url(#oral-tissue)"/><path d="M117 102q122-46 246 0l-8 24q-119-28-230 0z" fill="#ded6ba"/><path d="M174 243q65-57 133 0" fill="#b37876"/><g transform="translate(${x} ${y})"><path d="M-32 9q-18-25 7-36 20-18 36 2 29 8 15 34-26 20-58 0" fill="${t.specimen?'#a2746d':'#ca9a86'}" stroke="#dfb5a0" stroke-width="3"/><path d="M-19-8l15 13 16-17m-18-3l11 25" stroke="#b67b71" stroke-width="3"/>${t.specimen?`<ellipse cx="4" cy="7" rx="10" ry="7" fill="${t.hemostasis?'#a08072':'#9c5e58'}"/>`:''}${t.found?'<circle r="41" fill="none" stroke="#d7d8a6" stroke-width="2" stroke-dasharray="5 5"/>':''}</g>${t.stage==='cautery'?`<path d="M375 300L${x+12} ${y+14}" stroke="#b4c6bc" stroke-width="5"/><path d="M375 300l-43-36" stroke="#77a3a0" stroke-width="13"/>`:''}<text x="22" y="26" font-size="11" letter-spacing="2" fill="#cadacb">ORAL / HEADLIGHT VIEW</text><path d="M137 37l28 21m178-21l-28 21" stroke="#f2dfad" stroke-width="3" opacity=".7"/>`,'頭燈下的口腔簡化視野：一處不規則病灶');}
export function localVisual(t){
  if(t.kind==='ear'&&['scope','instrument','inject','rest','check'].includes(t.stage))return earView(t);
  if(t.kind==='oral'&&['inspect','local','instrument','sample','cautery'].includes(t.stage))return oralView(t);
  if(['label','handoff'].includes(t.stage))return npxSpecimen(t).replaceAll('NPX','ORAL').replaceAll('鼻咽','口腔');
  return npxDrape(t).replaceAll('NPX BIOPSY',t.kind==='ear'?'EAR INJECTION':'ORAL BIOPSY');
}
